/* Alkyon 4 · «Πώς δουλεύει» (#help) και «Τι νέο υπάρχει» (v31z547)
   ΚΑΝΟΝΑΣ: σε κάθε νέα λειτουργία ενημερώνονται (α) η ενότητα της στο HELP και (β) μια γραμμή στο NEWS με την έκδοση.
   Το «Τι νέο» εμφανίζεται μία φορά στους χρήστες που είχαν ήδη την εφαρμογή (alkyon-v4-news = τελευταία έκδοση που είδαν). */
(function(){
'use strict';
var B=window.AK, h=B.h, T=B.T, ls=B.ls;
/* [τίτλος, [[κείμενο, σύνδεσμος (προαιρετικό), κείμενο συνδέσμου]]] */
var HELP=[
 [T('Πρώτα βήματα','First steps'),[
  [T('Το Alkyon (αλκυόνη) σου δείχνει τη σωστή στιγμή για ψάρεμα: ήλιος, φεγγάρι, πίεση, άνεμος και κύμα σε έναν βαθμό 0–100. Για να το έχεις σαν εφαρμογή, πρόσθεσέ το στην αρχική οθόνη του κινητού.','Alkyon (the kingfisher) shows you the right moment to fish: sun, moon, pressure, wind and waves in one 0–100 score. To use it like an app, add it to your phone’s home screen.')],
  [T('Άνοιξε τις ειδοποιήσεις: χωρίς αυτές δεν έρχονται καλές μέρες, πλάνο εξόδου, καιρός στην έξοδο και «ώρα να γυρίσεις».','Turn on alerts: without them you get no good days, trip plans, weather on trips or “time to head back”.'),'#alerts',T('Ειδοποιήσεις','Alerts')],
  [T('Βάλε όρια ασφαλείας (ή μήκος σκάφους για αυτόματη πρόταση) και λιμάνι: από αυτά βγαίνουν οι ώρες «πάνω από τα όρια» και ο χρόνος επιστροφής.','Set safety limits (or boat length for a suggestion) and a home port: they drive “over your limits” hours and the time home.'),'#boat',T('Σκάφος','Boat')],
  [T('Όρισε επαφή ασφαλείας: ειδοποιείται αν δεν γυρίσεις στην ώρα σου.','Set a safety contact: they are alerted if you are not back on time.'),'#profile',T('Προφίλ','Profile')],
  [T('Λογαριασμός (δωρεάν): τα δεδομένα σου συγχρονίζονται και κάθε εβδομάδα κρατιέται αντίγραφο στο cloud (επαναφορά από Προφίλ › Λογαριασμός). Χρειάζεται για φίλους, κοινότητα, αυτόματη ειδοποίηση ασφαλείας και ρολόι. Στην εγγραφή και στο «Ξέχασα τον κωδικό» έρχεται email με κωδικό: γράψ\' τον στην εφαρμογή ή πάτα τον σύνδεσμο.','Account (free): your data syncs, and a weekly cloud backup is kept (restore from Profile › Account). It is needed for friends, community, automatic safety alerts and the watch. On sign-up and “Forgot password” you get an email with a code: type it in the app or tap the link.'),'#profile',T('Λογαριασμός','Account')],
  [T('Κάτι δεν δουλεύει; Προφίλ › Έλεγχος συστήματος: δείχνει τι λειτουργεί και τι όχι, με τι να κάνεις. Τα σφάλματα στέλνονται αυτόματα για διόρθωση.','Something not working? Profile › System check shows what works and what doesn’t, and what to do. Errors are sent automatically for fixing.'),'#check',T('Έλεγχος','Check')]]],
 [T('Πρόγνωση','Forecast'),[
  [T('Περασμένες μέρες: αριστερά από το «Σήμερα», στη λωρίδα των ημερών (σύρε τη λωρίδα προς τα δεξιά). Χθες και προχθές τις βλέπεις ολόκληρες, ώρα με ώρα. Πιο παλιές μέρες (έως 7) βλέπεις σε σύνοψη, με τον βαθμό, την καλύτερη ώρα και τα ψάρια σου εκείνη τη μέρα. Το ιστορικό κρατιέται 90 μέρες για κάθε τοποθεσία, με όλες τις συνθήκες της μέρας: άνεμο και ριπές, κύμα και περίοδο, ρεύμα (και σε βάθος), θερμοκρασία νερού και θερμοκλινές, ορατότητα, πίεση, καιρό, ήλιο, σελήνη και τον βαθμό ανά ώρα. Ρεύμα, ορατότητα και θερμοκλινές κρατιούνται για τις μέρες που άνοιξες την Πρόγνωση.','Past days: to the left of «Today» in the day strip (swipe the strip to the right). Yesterday and the day before are shown in full, hour by hour. Older days (up to 7) are shown as a summary with the score, best time and your catches that day. History is kept for 90 days per place, with all the conditions of the day: wind and gusts, waves and period, current (also at depth), water temperature and thermocline, visibility, pressure, weather, sun, moon and the score by hour. Current, visibility and thermocline are kept for the days you opened the Forecast.')],
  [T('Κάρτα «Τώρα»: «📍 Πού να πάω» δείχνει τα σημεία σου με τον καλύτερο βαθμό· «🗺 Στον χάρτη» ανοίγει τον χάρτη στην τοποθεσία. Η έναρξη εξόδου και το νέο ψάρι είναι στο κεντρικό κουμπί.','«Now» card: «📍 Where to go» shows your spots with the best score; «🗺 On the map» opens the map at the place. Starting a trip and logging a catch are on the main button.')],
  [T('Ρεύμα θάλασσας (σήμερα): ταχύτητα σε κόμβους και κατεύθυνση (προς τα πού πάει το νερό), ανά 3 ώρες και σε βάθος. Από το μοντέλο Copernicus Μεσογείου.','Sea current (today): speed in knots and direction (where the water is going), every 3 hours and at depth. From the Copernicus Mediterranean model.')],
  [T('Κάθε μέρα έχει βαθμό 0–100 και καλύτερες ώρες. Πάτα μια μπάρα στο «Ανά ώρα» για τα στοιχεία της ώρας· κόκκινο = πάνω από τα όριά σου, με τον λόγο.','Each day has a 0–100 score and best hours. Tap a bar in “By hour” for details; red = over your limits, with the reason.'),'#forecast',T('Πρόγνωση','Forecast')],
  [T('«Για σένα»: όταν η προσωπική πρόγνωση (από τις δικές σου εξόδους) αποδειχθεί καλύτερη από τον μέσο όρο σου, η κάρτα της ημέρας δείχνει και τον δικό σου βαθμό. Λεπτομέρειες στην καρτέλα «Δικά μου».','“For you”: once your personal forecast (from your own trips) proves better than your average, the day card also shows your own score. Details in the “Mine” tab.')],
  [T('«Θα βγω αυτή τη μέρα»: υπενθύμιση το προηγούμενο βράδυ, ~1 ώρα πριν από την καλύτερη ώρα, και ειδοποίηση αν χαλάσει ο καιρός.','“I’ll go out this day”: reminder the evening before, ~1 hour before the best time, and an alert if the weather turns.')],
  [T('Με το «Θα βγω» κατεβαίνουν μόνα τους ο χάρτης και η πρόγνωση της περιοχής (με WiFi ή 4G/5G), για χρήση χωρίς σήμα στη θάλασσα. Ρύθμιση: Ειδοποιήσεις › Πριν την έξοδο.','With “I’ll go out” the area’s map and forecast download by themselves (WiFi or 4G/5G) for use without signal at sea. Setting: Notifications › Before the trip.'),'#alerts',T('Ρύθμιση','Setting')],
  [T('Τοποθεσία: αναζήτηση, «Διάλεξε στον χάρτη» (ανοίγει τον Χάρτη, σταυρός στο κέντρο) ή συντεταγμένες.','Location: search, “Pick on the map” (crosshair) or coordinates.')],
  [T('«Τι δούλεψε σε παρόμοιες μέρες»: δόλωμα, τεχνική, βάθος και ώρα από τις δικές σου ψαριές σε παρόμοιες συνθήκες.','“What worked on similar days”: bait, technique, depth and time from your own catches in similar conditions.')],
  [T('Θερμοκρασία σε βάθος (σκάφος/ψαροντούφεκο): πού είναι το θερμοκλινές σήμερα. Ορατότητα νερού για ψαροντούφεκο: από δορυφόρο όταν δεν έχει σύννεφα, αλλιώς εκτίμηση από κύμα και βροχή.','Temperature at depth (boat/spearfishing): where today’s thermocline is. Water visibility for spearfishing: from satellite when there are no clouds, otherwise estimated from waves and rain.')],
  [T('Καρτέλα «Είδη»: ποιο ψάρι ταιριάζει σε ποια μέρα και η εποχή κάθε είδους μήνα με μήνα.','“Species” tab: which fish suits which day, and each species’ season month by month.')]]],
 [T('Χάρτης','Map'),[
  [T('Στρώσεις › «Τροφή» (χλωροφύλλη) και «Νερό δορυφόρου» (θερμοκρασία 1 km): εκεί που αλλάζει απότομα το χρώμα (μέτωπο) μαζεύεται η τροφή και τα ψάρια. Δορυφόρος Copernicus, συνήθως της προηγούμενης μέρας.','Layers › «Food» (chlorophyll) and «Satellite water» (1 km temperature): where the colour changes sharply (a front), food and fish gather. Copernicus satellite, usually the previous day.')],
  [T('Κουμπιά πάνω: άνεμος, κύμα, ρεύματα, νερό, βάθη. Η μπάρα ώρας κάτω: πάτα μια μέρα για να πας εκεί, «Τώρα» για επιστροφή.','Top buttons: wind, waves, currents, water, depths. Time bar at the bottom: tap a day to jump there, “Now” to return.'),'#map',T('Χάρτης','Map')],
  [T('Περιστροφή με δύο δάχτυλα· η πυξίδα πάνω αριστερά τον επαναφέρει με τον βορρά πάνω.','Rotate with two fingers; the compass at the top left resets north up.')],
  [T('Αν σύρεις τον χάρτη, σταματά να σε ακολουθεί· το κουμπί θέσης τον ξαναφέρει σε σένα.','Dragging the map stops following you; the position button brings it back.')],
  [T('Χάρτης χωρίς σήμα: κουμπί χάρτη (πάνω δεξιά) › «Χάρτης εκτός σύνδεσης» › Κατέβασμα.','Offline map: map button (top right) › “Offline map” › Download.')],
  [T('Πάτημα στη θάλασσα: κύμα, άνεμος και ρεύμα σε εκείνο το σημείο. Παρατεταμένο πάτημα: αποθήκευση σημείου.','Tap the sea: waves, wind and current there. Long press: save a spot.')],
  [T('Πάτα ένα ψάρι ή σημείο στον χάρτη για λεπτομέρειες· από εκεί και «Διαγραφή» (με «Αναίρεση» για λίγα δευτερόλεπτα). Σε ομάδα ψαριών, σύρε αριστερά.','Tap a catch or spot on the map for details; “Delete” is there too (with “Undo” for a few seconds). In a group of catches, swipe left.')]]],
 [T('Έξοδος','Trip'),[
  [T('Ρολόι Garmin, οθόνες: Σήμερα (δαχτυλίδι 24 ωρών: πράσινες/κίτρινες οι καλές ώρες, χοντρό το καλύτερο παράθυρο, άσπρη κουκκίδα το τώρα, ανατολή και δύση πάνω στο δαχτυλίδι), Έξοδος, Επόμενες μέρες, Πίεση (γράφημα 12 ωρών με κλίμακα hPa και την επόμενη κορυφή ή πάτο). Τη νύχτα η οθόνη γίνεται κόκκινη (ρύθμιση στο Connect IQ).','Garmin watch screens: Today (24-hour ring: good hours green/yellow, the best window thicker, white dot = now, sunrise and sunset on the ring), Trip, Next days, Pressure (12-hour chart with hPa scale and the next peak or low). At night the screen turns red (setting in Connect IQ).')],
  [T('Καλύτερα σημεία: Πρόγνωση › «Πού να πάω» › «Βρες τα καλύτερα σημεία γύρω μου», ή Χάρτης › Στρώσεις › «Καλύτερα σημεία» (ψάχνει γύρω από το κέντρο του χάρτη· με μικρότερο ζουμ ψάχνει πιο μακριά, έως 60 km). Βαθμολογεί σημεία θάλασσας από: ήρεμη θάλασσα μέσα στα όρια σου, μέτωπα χλωροφύλλης (τροφή) και θερμοκρασίας, ήπιο ρεύμα, απότομο βυθό και καλό βάθος, και τα ψάρια σου εκεί. Δείχνει τα 5 καλύτερα με εξήγηση και πιθανά ψάρια (τα δικά σου ψάρια εκεί πρώτα). Με βάρκα ψάχνει ως όσο μακριά πας (ρύθμιση στη λίστα, 30 km)· πάνω από 300 m βάθος μόνο για τρόλινγκ. Από ακτή έως 50 m, ψαροντούφεκο έως 30 m. Όσο είναι ανοιχτό, όταν μετακινείς ή αλλάζεις ζουμ στον χάρτη ψάχνει ξανά μόνο του εκεί που κοιτάς· το κίτρινο κουμπί κάτω ανοίγει τη λίστα. Ενδεικτικό, όχι εγγύηση.','Best spots: Forecast › «Where to go» › «Find the best spots around me», or Map › Layers › «Best spots» (searches around the map centre; zoom out to search further, up to 60 km). It scores sea points by: calm sea within your limits, chlorophyll (food) and temperature fronts, gentle current, steep seabed and good depth, and your catches there. Shows the best 5 with reasons and likely fish (your own catches there first). By boat it searches as far as you go (setting in the list, 30 km); deeper than 300 m only for trolling. Shore up to 50 m, spearfishing up to 30 m. While it is on, moving or zooming the map searches again where you look; the yellow button at the bottom opens the list. Indicative, not a guarantee.')],
  [T('Ρεύματα στον χάρτη: στη Μεσόγειο από το Copernicus Μεσογείου (~4 km, με μετρήσεις), αλλού από το Open-Meteo (~8 km). Πάτα στη θάλασσα για να δεις την πηγή.','Currents on the map: in the Mediterranean from Copernicus Mediterranean (~4 km, with measurements), elsewhere from Open-Meteo (~8 km). Tap the sea to see the source.')],
  [T('Ρολόι, σελίδα «Σημείο» (3η): βέλος και απόσταση ως το τελευταίο ψάρι, την αφετηρία της εξόδου, την άγκυρα ή τα αποθηκευμένα σημεία σου (τα 12 κοντινότερα). START: αλλαγή στόχου ή γρήγορο ψάρι.','Watch, «Spot» page (3rd): arrow and distance to your last catch, the trip start, the anchor or your saved spots (the 12 nearest). START: change target or quick catch.')],
  [T('Ρολόι, άγκυρα: START › «Άγκυρα». Αν το σκάφος φύγει πάνω από 40 m (ρύθμιση στο Connect IQ), δονείται δυνατά και κάνει ήχο. START σταματά τον συναγερμό. Η εφαρμογή πρέπει να μείνει ανοιχτή στο ρολόι.','Watch, anchor: START › «Anchor». If the boat moves more than 40 m (setting in Connect IQ) it vibrates hard and beeps. START stops the alarm. The app must stay open on the watch.')],
  [T('Ρολόι, ειδοποιήσεις: 30 λεπτά πριν την καλύτερη ώρα (βαθμός από 60), και στην έξοδο «Ώρα να γυρίσεις» με βάση την απόσταση ως την αφετηρία και την ταχύτητα του σκάφους (ρύθμιση, 15 kn).','Watch alerts: 30 minutes before the best time (score 60+), and on a trip «Time to head back» from the distance to the start and your boat speed (setting, 15 kn).')],
  [T('Ρολόι, watch face: ο σημερινός βαθμός μπορεί να μπει σε μία θέση του watch face (complication «Alkyon»), σε όσα watch face το επιτρέπουν. Στο δαχτυλίδι οι γαλάζιες κουκκίδες είναι οι ηλιοσεληνιακές ώρες (μεγάλη = κύρια).','Watch face: today’s score can go into a watch-face slot (complication «Alkyon»), on faces that allow it. On the ring, the blue dots are the solunar times (big = major).')],
  [T('Έξοδος στο ρολόι: το κόκκινο δαχτυλίδι γεμίζει ως την ώρα επιστροφής που δήλωσες στο κινητό (αλλιώς ως τη δύση) και γράφει πόσο απομένει. Βλέπεις ψάρια, km και ταχύτητα σε κόμβους.','Trip on the watch: the red ring fills up to the return time you set on the phone (otherwise to sunset) and shows the time left. You also see fish, km and speed in knots.')],
  [T('Έξοδος από το ρολόι Garmin: SELECT › «Έναρξη εξόδου». Καταγράφεται δραστηριότητα «Ψάρεμα» με GPS· κάθε ψάρι μπαίνει στην ίδια έξοδο. Στο τέλος («Τέλος εξόδου» ή BACK) πάει στο Garmin Connect, και η έξοδος με τη διαδρομή έρχεται εδώ.','Trip from the Garmin watch: SELECT › «Start trip». A «Fishing» activity is recorded with GPS; every catch goes into the same trip. At the end («End trip» or BACK) it goes to Garmin Connect, and the trip with its track comes here.')],
  [T('Ξεκίνα από το κεντρικό κουμπί. Βάλε ώρα επιστροφής· αν δεν γυρίσεις, ειδοποιείται η επαφή σου.','Start from the centre button. Set a return time; if you are not back, your contact is alerted.')],
  [T('Πράσινο ψάρι = έπιασα, κόκκινο = χάθηκε, 🐡 = λαγοκέφαλος ή «έφαγε το δόλωμα» (δεν μετράνε ως ψάρια). Κράτα πατημένο για διαγραφή του τελευταίου.','Green fish = caught, red = lost, 🐡 = toadfish or “bait taken” (not counted as catches). Hold to delete the last one.')],
  [T('Μεγάλα κουμπιά (4 τετράγωνα): για βρεγμένα χέρια και κύμα. MOB με παρατεταμένο πάτημα.','Big buttons (4 squares): for wet hands and waves. MOB with a long press.')],
  [T('Φωνή 🎤: «τρία λαβράκια ενάμισι κιλό με γαρίδα», «σαργός 800 γραμμάρια το άφησα», «χάθηκε», «λαγοκέφαλος». Στον χάρτη, στα μεγάλα κουμπιά και στη φόρμα ψαριού. Χρειάζεται σήμα.','Voice 🎤: “three sea bass one and a half kilos with shrimp”, “bream 800 grams released”, “lost”, “toadfish”. On the map, the big buttons and the catch form. Needs signal.')],
  [T('Νυχτερινή λειτουργία 🌙: κόκκινη οθόνη, μόνη της μετά τη δύση.','Night mode 🌙: red screen, on by itself after sunset.')],
  [T('Με κλειστό κινητό σε ειδοποιεί για καταιγίδα, καιρό πάνω από τα όρια, δύση και ώρα επιστροφής, με βάση την απόσταση από το λιμάνι σου.','With the phone locked you are alerted to storms, weather over your limits, sunset and your return time, based on the distance to your port.')],
  [T('Κοινή έξοδος: στην έναρξη επίλεξε «Οι φίλοι μου βλέπουν τη θέση μου».','Shared trip: at the start choose “My friends see my position”.')],
  [T('Ρολόι Garmin: Προφίλ › Ρολόι Garmin › κωδικός σύνδεσης. Στο ρολόι: βαθμός και καλύτερη ώρα, πίεση (ειδοποίηση πριν την κορυφή ή τον πάτο, και όταν αρχίζει να πέφτει ή να ανεβαίνει, όπως στο κινητό) και SELECT για Ψάρι / Χάθηκε / Λαγοκέφαλος, με ώρα και θέση.','Garmin watch: Profile › Garmin watch › link code. On the watch: score and best time, pressure (alert before a peak or low, and when it starts to fall or rise, like on the phone) and SELECT for Fish / Lost / Toadfish, with time and position.')],
  [T('Ψάρεμα από ακτή: αν σταθείς σε σημείο σου, ρωτά «Ξεκινάς ψάρεμα;».','Shore fishing: if you stop at one of your spots it asks “Starting to fish?”.')]]],
 [T('Ημερολόγιο','Logbook'),[
  [T('Ψάρια, έξοδοι, σημεία, εργαλεία. Στα Στατιστικά: στόχοι, ρεκόρ ανά είδος, λαγοκέφαλοι χωριστά, σύγκριση χρονιών.','Catches, trips, spots, gear. In Stats: goals, records by species, toadfish separately, year comparison.'),'#log',T('Ημερολόγιο','Logbook')],
  [T('Έξοδος που δεν κατέγραψες; Ημερολόγιο › Έξοδοι › «+ Παλιά έξοδος»: ημερομηνία, σημείο, ώρες, ψάρια και σημειώσεις.','A trip you did not log? Logbook › Trips › “+ Past trip”: date, spot, hours, catches and notes.'),'#log',T('Ημερολόγιο','Logbook')],
  [T('Στη φόρμα ψαριού: αν ο λαγοκέφαλος έκοψε αγκίστρι ή τεχνητό, πάτα το για −1 από τον εξοπλισμό.','In the catch form: if a toadfish cut a hook or lure, tap it for −1 from your tackle.')],
  [T('Εργαλεία (δίχτυα, παραγάδια): «Στον χάρτη» δείχνει τη ρίψη και το ανέβασμα, ακόμα κι αν έχει τελειώσει· το ✕ πάνω τα κρύβει.','Gear (nets, longlines): “On the map” shows the set and haul, even when finished; the ✕ at the top hides them.')],
  [T('Σκάφος › Λήξεις: «+ Νέα λήξη» προτείνει συνηθισμένα (δίπλωμα, σωσίβια, τρέιλερ, μαρίνα…) ή γράφεις δικό σου. Όσα δεν χρειάζεσαι τα αφαιρείς.','Boat › Expiries: “+ New expiry” suggests common ones (licence, lifejackets, trailer, marina…) or type your own. Remove the ones you don’t need.'),'#boat',T('Σκάφος','Boat')]]],
 [T('Ειδοποιήσεις','Alerts'),[
  [T('Μήνυμα για καλή μέρα: μόνο αν κάποια τοποθεσία σου έχει καλό βαθμό, σου λέει ποια και ποια ώρα. Διαλέγεις στις Ειδοποιήσεις: το προηγούμενο βράδυ (19:00–23:00, προεπιλογή), το πρωί (07:00–10:00), και τα δύο ή όχι.','Good-day message: only if one of your places scores well, it tells you which and when. Choose in Alerts: the evening before (19:00–23:00, default), the morning (07:00–10:00), both or off.')],
  [T('Καλές μέρες (με τον στόχο σου), αλλαγές πίεσης, μέτωπα θερμοκρασίας, εβδομαδιαία σύνοψη την Κυριακή. Ησυχία 23:00–07:00 εκτός από ασφάλεια και πλάνο.','Good days (your target), pressure changes, temperature fronts, a Sunday weekly summary. Quiet 23:00–07:00 except safety and plans.'),'#alerts',T('Ειδοποιήσεις','Alerts')]]],
 [T('Φίλοι','Friends'),[
  [T('Φτιάξε κωδικό και στείλε τον σύνδεσμο: ο φίλος τον πατά και ο κωδικός μπαίνει μόνος του.','Create a code and send the link: your friend taps it and the code fills in by itself.'),'#friends',T('Φίλοι','Friends')]]]
];
/* έκδοση → αλλαγές (νεότερες πρώτες). Προσθέτεις γραμμή εδώ σε κάθε νέα λειτουργία. */
var NEWS=[
 ['1.8.6',[T('Καθαρός χάρτης, λιγότερος θόρυβος: ένα κουμπί «ψάρι» δεξιά (πάτημα = ψάρι · κράτημα = χαμένο, λαγοκέφαλος, μεγάλα κουμπιά, διαγραφή τελευταίου), χωρίς τα «0». Η μπάρα ώρας πιο λεπτή: οι μέρες φαίνονται όσο την πιάνεις. Η κάρτα «Σημείο» πιο μικρή. Η κάρτα ΨΑΡΕΥΩ ανοιχτόχρωμη τη μέρα (σκούρα στη νυχτερινή).','Clean map, less clutter: one “fish” button on the right (tap = catch · hold = lost, toadfish, big buttons, delete last), without the “0”. A thinner time bar: the days show while you hold it. A smaller “Point” card. The FISHING card is light by day (dark in night mode).'),T('Χάρτης: πιο λεπτές και διάφανες γραμμές βάθους, λιγότερα βέλη ρευμάτων με χρώμα ανάλογα με τη δύναμη, ζώνες «απαγορεύεται» με λεπτό διακεκομμένο περίγραμμα.','Map: thinner, lighter depth lines, fewer current arrows coloured by strength, no-fishing zones with a thin dashed outline.'),T('Πρόγνωση: μικρότερος τίτλος και όνομα περιοχής (π.χ. «Λάρα · εδώ»). Οι μέρες ξεκινούν από σήμερα με εικονίδιο καιρού (οι περασμένες πίσω από το «‹»). Αντί για τον κύκλο με τον βαθμό, γιατί είναι έτσι η μέρα. Βελάκι ανέμου στο «Τώρα». Οι ευκαιρίες στα σημεία σου αμέσως κάτω από το «Τώρα». Στο «Ανά ώρα» η σελήνη είναι λεπτή μωβ γραμμή. Θερμοκλινές σε ένα διάγραμμα. Έκθεση ακτής σε ροδέλα (οι αριθμοί από κάτω).','Forecast: smaller title and area name (e.g. “Lara · here”). Days start today with a weather icon (past days behind “‹”). Instead of the score circle, why the day is like this. Wind arrow in “Now”. Chances at your spots right below “Now”. In “By hour” the moon is a thin purple line. Thermocline as one chart. Coast exposure as a rose (numbers below).')]],
 ['1.8.5',[T('Μπάρα πάνω: σε έξοδο δείχνει τις τιμές στη θέση σου (📍) μόνο όσο ο χάρτης σε ακολουθεί. Μόλις κουνήσεις τον χάρτη αλλού, δείχνει τις τιμές στον σταυρό (✛)· πάτα ◎ για να γυρίσεις στη θέση σου.','Top bar: on a trip it shows the values at your position (📍) only while the map follows you. As soon as you move the map elsewhere it shows the values at the cross (✛); tap ◎ to go back to your position.'),T('«Στεριά» με την ακριβή ακτογραμμή: κοντά στην ακτή δεν γράφει πια «στεριά» για σημείο στη θάλασσα.','“Land” uses the exact coastline: near the shore it no longer says “land” for a point at sea.'),T('Πρόγνωση › Ρεύμα θάλασσας: δεν γράφει πια «null» όταν δεν υπάρχει ωριαία πρόγνωση ρεύματος.','Forecast › Sea current: no longer shows “null” when there is no hourly current forecast.')]],
 ['1.8.4',[T('Αέρας πάνω στον χάρτη χωρίς «σκαλοπάτια» στην ακτή: η ακριβής ακτογραμμή κρατιέται για μεγαλύτερη περιοχή και δεν χάνεται σε κάθε μικρή κίνηση του χάρτη.','Wind on the map without “steps” at the coast: the exact coastline is kept for a larger area and is not lost on every small map move.'),T('Λιγότερα κουτάκια άνεμου/κύματος πάνω στον χάρτη, πιο διάφανα, και όχι πάνω στον σταυρό. Οι αριθμοί βάθους στις γραμμές 5/10/20 m δεν πέφτουν πια ο ένας πάνω στον άλλο.','Fewer, lighter wind/wave boxes on the map, and none on the cross. Depth numbers on the 5/10/20 m lines no longer overlap.'),T('Κάρτα ΨΑΡΕΥΩ: τρίτη στήλη ΡΕΥΜΑ, πόσο και προς τα πού σε σπρώχνει το ρεύμα στη θέση σου (όταν είναι ανοιχτά τα ρεύματα).','FISHING card: a third column CURRENT, how hard and which way the current pushes you at your position (when currents are on).'),T('Άνεμος για όλους από ένα κοινό αρχείο: για τα νερά της Κύπρου ο άνεμος (ECMWF και ICON-EU) έρχεται από ένα αρχείο που φτιάχνεται κάθε 3 ώρες, ίδιο για όλους τους χρήστες. Έτσι δεν υπάρχει όριο αιτημάτων όσο κι αν μεγαλώσει η εφαρμογή. Εκτός Κύπρου, όπως πριν.','Wind for everyone from one shared file: for Cyprus waters the wind (ECMWF and ICON-EU) comes from a file built every 3 hours, the same for all users. So there is no request limit however much the app grows. Outside Cyprus, as before.')]],
 ['1.8.3',[T('Ο σταυρός δεν κρύβεται πια πίσω από την κάρτα σημείου ή την κάρτα ΨΑΡΕΥΩ: μπαίνει στη μέση του χώρου που φαίνεται, και οι τιμές (μπάρα πάνω, «στον σταυρό» κάτω) είναι για εκεί.','The cross no longer hides behind the point card or the FISHING card: it sits in the middle of the visible area, and the values (top bar, “at the cross” below) are for that spot.'),T('Ρεύματα με πρόγνωση: τα βέλη αλλάζουν με τη μπάρα ώρας, έως 5 μέρες μπροστά (Open-Meteo, ωριαία). «Τώρα» παραμένει το Copernicus Μεσογείου όπου υπάρχει.','Currents with a forecast: the arrows change with the time bar, up to 5 days ahead (Open-Meteo, hourly). “Now” stays Copernicus Mediterranean where available.'),T('Πάνω στη στεριά: η κάρτα σημείου και η μπάρα γράφουν «στεριά», χωρίς βάθος, κύμα και ρεύμα.','On land: the point card and the bar say “land”, with no depth, waves or current.')]],
 ['1.8.2',[T('Το κουμπί NU / CU / HU χανόταν όταν έφευγες από τον χάρτη και ξαναγύριζες (π.χ. στο Ημερολόγιο και πίσω)· τώρα μένει πάντα δίπλα στο MOB σε έξοδο.','The NU / CU / HU button disappeared after leaving the map and coming back (e.g. to the Logbook and back); now it always stays next to MOB on a trip.'),T('Η μπάρα πάνω αλλάζει αμέσως μαζί με την ώρα (όταν σέρνεις ή τρέχει η μπάρα ώρας) και μαζί με τον σταυρό, χωρίς καθυστέρηση. Το ρεύμα φαίνεται μόνο για «τώρα»· σε άλλη ώρα κρύβεται, γιατί δεν έχουμε πρόγνωση ρεύματος.','The top bar now changes at once with the time (when you drag or play the time bar) and with the cross, with no delay. The current shows only for “now”; at other times it hides, as there is no current forecast.')]],
 ['1.8.1',[T('Μπάρα του καθαρού χάρτη με κατευθύνσεις: βελάκι και τιμή για άνεμο, κύμα και ρεύμα (όσα στρώματα είναι ανοιχτά). Σε έξοδο δείχνει τις τιμές στη θέση σου (📍)· αλλιώς στον σταυρό στο κέντρο του χάρτη (✛) και αλλάζει καθώς κουνάς τον χάρτη.','Clean-map bar with directions: arrow and value for wind, waves and current (whichever layers are on). On a trip it shows the values at your position (📍); otherwise at the cross in the centre of the map (✛) and changes as you move the map.'),T('Η «Κάρτα καιρού» έφυγε από το μενού του καθαρού χάρτη: εκεί η μπάρα πάνω είναι η κάρτα καιρού.','“Weather card” removed from the clean-map menu: there the top bar is the weather card.'),T('Χάρακας: ξεκινάς από το πρώτο σημείο που πατάς (όχι αυτόματα από τη θέση σου)· για αρχή από εσένα πάτα ◎. Το κουμπί «⏱ 8 kn» είναι η ταχύτητα με την οποία υπολογίζεται ο χρόνος, όταν το GPS δεν δίνει δική σου ταχύτητα· πάτα το για 3 / 5 / 8 / 12 / 20 kn.','Ruler: you start from the first point you tap (not automatically from your position); to start from you tap ◎. The “⏱ 8 kn” button is the speed used for the time when GPS gives no speed of your own; tap it for 3 / 5 / 8 / 12 / 20 kn.')]],
 ['1.8.0',[T('Η λαβή του μενού στη δεξιά άκρη ανέβηκε πιο ψηλά, για να μην πέφτει πάνω στα κουμπιά των ψαριών.','The menu handle on the right edge moved higher so it no longer sits on the catch buttons.')]],
 ['1.7.9',[T('Καθαρός χάρτης: λαβή στη δεξιά άκρη της οθόνης (όπως το Edge panel της Samsung). Πάτα την ή σύρε την αριστερά και ανοίγει το μενού.','Clean map: a handle on the right edge of the screen (like Samsung’s Edge panel). Tap it or swipe it left to open the menu.'),T('Πάνω σε μία γραμμή δεξιά: MOB · NU/CU/HU · η θέση μου. Η μπάρα αριστερά είναι ανοιχτόχρωμη και δείχνει μόνο άνεμο και κύμα, για να διαβάζεται καλά. Η κάρτα ΨΑΡΕΥΩ πιάνει όλο το πλάτος από κάτω.','On top, one row on the right: MOB · NU/CU/HU · my position. The bar on the left is light and shows only wind and waves, so it reads well. The FISHING card spans the width below.'),T('Μενού σε σειρά σημαντικότητας και όλα ανοιχτά (χωρίς να πατάς ομάδες): Στρώματα, Έτοιμα, Καιρός και θάλασσα, Εργαλεία, Τα δικά μου, Χάρτης και βάθη, Θάλασσα και κανόνες, Ενέργειες· μόνο το Υπόμνημα ανοιγοκλείνει.','Menu in order of importance and all open (no tapping groups): Layers, Presets, Weather and sea, Tools, My data, Map and depths, Sea and rules, Actions; only the Legend opens and closes.')]],
 ['1.7.8',[T('Καθαρός χάρτης: το μενού ανοίγει πλέον από δεξιά, όπως στο Windy. Αριστερά μένει ζωντανός ο χάρτης και μετακινείται ώστε η περιοχή σου να φαίνεται· ό,τι πατάς (άνεμος, κύμα, ρεύματα, νερό, βάθη, έτοιμα) αλλάζει τον χάρτη αμέσως, χωρίς να κλείσεις το μενού.','Clean map: the menu now opens from the right, like Windy. The map stays live on the left and shifts so your area shows; whatever you tap (wind, waves, currents, water, depths, presets) changes the map at once, without closing the menu.'),T('Ανοίγει: πάτημα στη μπάρα πάνω ή σύρσιμο αριστερά. Κλείνει: σύρσιμο δεξιά, πάτημα στον χάρτη αριστερά ή το «πίσω» του κινητού.','Open: tap the top bar or swipe it left. Close: swipe right, tap the map on the left, or the phone’s back button.')]],
 ['1.7.7',[T('Διόρθωση: στην 1.7.6 ο δορυφορικός χάρτης έβγαινε μαύρος. Επιστροφή στον τρόπο της 1.7.5 (σε ανοιχτή θάλασσα με πολύ ζουμ μπορεί να φαίνεται ξανά το γκρι «Map data not yet available»· κάνε λίγο ζουμ έξω).','Fix: in 1.7.6 the satellite map showed black. Back to the 1.7.5 way (in open sea at high zoom the grey “Map data not yet available” may show again; zoom out a little).')]],
 ['1.7.6',[T('Σε έξοδο το κεντρικό κουμπί γίνεται πράσινο με τον χρόνο που μένει (π.χ. 3:59)· κόκκινο που αναβοσβήνει όταν πέρασε η ώρα επιστροφής. Πάτημα: η έξοδος (Νέο ψάρι, +30 λεπτά, Τέλος εξόδου, SOS). Κράτα πατημένο: καταγραφή με φωνή. Η πράσινη μπάρα «Σε έξοδο» έφυγε, για να φαίνεται ο χάρτης. Νέο ψάρι και από τα κουμπιά δεξιά.','On a trip the centre button turns green with the time left (e.g. 3:59); red and pulsing when past your return time. Tap: the trip (New catch, +30 min, End trip, SOS). Long-press: voice log. The green “On a trip” bar is gone so the map shows. New catch also from the buttons on the right.'),T('Καθαρός χάρτης σε έξοδο: το κουμπί NU / CU / HU (Βορράς πάνω / Πορεία πάνω / Πυξίδα πάνω) είναι πάντα κάτω από το MOB.','Clean map on a trip: the NU / CU / HU button (North up / Course up / Heading up) is always under MOB.'),T('Κάρτα ΨΑΡΕΥΩ: «χωρίς GPS» όταν δεν υπάρχει θέση.','FISHING card: “no GPS” when there is no position.')]],
 ['1.7.5',[T('Μενού του καθαρού χάρτη πιο σύντομο: κάθε στρώμα είναι μία γραμμή με διακόπτη (όχι μεγάλα πλακίδια). Λιγότερες ομάδες: «Χάρτης και βάθη» (τύπος χάρτη, αέρας πάνω στη στεριά, βάθη), «Καιρός και θάλασσα» (μαζί με το «Πού να πάω»), «Θάλασσα και κανόνες», «Τα δικά μου», «Ενέργειες», «Υπόμνημα».','Shorter clean-map menu: each layer is one line with a switch (no big tiles). Fewer groups: “Map and depths” (map type, wind over land, depths), “Weather and sea” (with “Where to go”), “Sea and rules”, “My data”, “Actions”, “Legend”.'),T('Τα «Έτοιμα» γράφουν τι ανοίγουν (π.χ. Συρτή βυθού: ρεύματα + βάθη).','Presets say what they turn on (e.g. Bottom trolling: currents + depths).'),T('Κάρτα ΨΑΡΕΥΩ / ΑΓΚΥΡΑ μικρότερη, δίπλα στο MOB, για να φαίνεται ο χάρτης. Αν δεν βρεθεί βάθος γράφει «–» αντί για «…» που δεν τελειώνει.','FISHING / ANCHORED card smaller, next to MOB, so the map shows. If no depth is found it shows “–” instead of an endless “…”.')]],
 ['1.7.4',[T('Μενού του καθαρού χάρτη, πιο δομημένο: πάνω Στρώματα, Έτοιμα (Συρτή βυθού, Καιρός, Νερό και μέτωπα, Καθαρός) και Εργαλεία (Συρτή, Άγκυρα, Χάρακας, Φωνητική καταγραφή, Νυχτερινή, Πυξίδα, Ειδοποιήσεις, Φωνή εφαρμογής, Πηγές). Από κάτω όλα τα υπόλοιπα σε ομάδες που ανοιγοκλείνουν: Χάρτης, Αέρας πάνω στη στεριά, Πού να πάω, Καιρός και θάλασσα, Βάθη, Θάλασσα και κανόνες, Τα δικά μου, Ενέργειες, Υπόμνημα.','Clean map menu, more structured: on top Layers, Presets (Bottom trolling, Weather, Water and fronts, Plain) and Tools (Trolling, Anchor, Ruler, Voice log, Night, Compass, Notifications, App voice, Sources). Below, everything else in groups that open and close: Map, Wind over land, Where to go, Weather and sea, Depths, Sea and rules, My data, Actions, Legend.'),T('Αέρας πάνω στη στεριά: Αχνός / Κανονικός (προεπιλογή, το χρώμα φαίνεται) / Πλήρης (όπως το Windy), με λεπτή ακτογραμμή. Άνεμος, κύμα και νερό κόβονται ακριβώς στην ακτή από ζουμ 7, χωρίς «σκαλοπάτια».','Wind over land: Faint / Normal (default, the colour shows) / Full (like Windy), with a thin coastline. Wind, waves and water are cut exactly at the coast from zoom 7, no more “steps”.'),T('Θερμοκρασία νερού: ακριβώς στην ακτή, «Στο σταυρό: 23,4°» στο υπόμνημα και επιλογή κλίμακας: της περιοχής (μικρές διαφορές) ή σταθερή 14–30° (ίδιο χρώμα = ίδια θερμοκρασία κάθε μέρα).','Water temperature: exactly at the coast, “At the cross: 23.4°” in the legend and a scale choice: this area (small differences) or fixed 14–30° (same colour = same temperature every day).'),T('Άνεμος: όταν η κοινή μνήμη φτάνει το όριο του Open-Meteo, ζητά απευθείας από το κινητό σου· αλλιώς γράφει «Ο άνεμος δεν ήρθε» (όχι «Φόρτωση…») και ξαναδοκιμάζει σε 3 λεπτά.','Wind: when the shared cache hits the Open-Meteo limit it asks directly from your phone; otherwise it says “No wind data” (not “Loading…”) and retries in 3 minutes.')]],
 ['1.7.3',[T('Η εφαρμογή σού μιλάει (Προφίλ › Ρυθμίσεις › Φωνή): «Σταμάτα στα 30 μολύβια», «Στον βυθό», «Βαράει βυθό, μάζεψε 2», «Ταχύτητα δυόμισι, ανέβασε», «Η άγκυρα σέρνει, 52 μέτρα», «Φτάνεις σε δύο λεπτά», «Έφτασες». Ηχείο, ακουστικό ή Bluetooth· διαλέγεις τι θες και πόσο δυνατά.','The app talks to you (Profile › Settings › Voice): “Stop at 30 leads”, “On the bottom”, “Hitting bottom, bring in 2”, “Speed two and a half, speed up”, “Anchor dragging, 52 metres”, “Arriving in two minutes”, “Arrived”. Speaker, headphones or Bluetooth; choose what and how loud.'),T('Καθαρός χάρτης σε έξοδο: η οθόνη αλλάζει μόνη της. ΠΗΓΑΙΝΩ (πάνω από 6 kn): ταχύτητα, πορεία, απόσταση και άφιξη. ΨΑΡΕΥΩ (αργά): ταχύτητα και βάθος κάτω από τη βάρκα. ΑΓΚΥΡΑ: απόσταση από την άγκυρα. Πάτα την ετικέτα για να την αλλάξεις με το χέρι· κλείνει από Προφίλ › Ρυθμίσεις › Χάρτης.','Clean map on a trip: the screen changes by itself. UNDERWAY (above 6 kn): speed, heading, distance and ETA. FISHING (slow): speed and depth below the boat. ANCHORED: distance from the anchor. Tap the label to switch by hand; turn off in Profile › Settings › Map.')]],
 ['1.7.2',[T('Νέος «Καθαρός» χάρτης (επιλογή): πάνω μόνο το MOB, η θέση σου και μία λεπτή μπάρα με τα ανοιχτά στρώματα και τις τιμές τους. Σύρε τη μπάρα κάτω (ή πάτα την) για όλα τα στρώματα, έτοιμους συνδυασμούς (Συρτή βυθού, Καιρός, Καθαρός χάρτης) και όλα τα εργαλεία. Κλείνει με σύρσιμο πάνω ή πάτημα στον χάρτη.','New “Clean” map (optional): on top only MOB, your position and one thin bar with the active layers and their values. Pull the bar down (or tap it) for all layers, presets (Bottom trolling, Weather, Plain map) and all tools. Swipe up or tap the map to close.'),T('Την πρώτη φορά σε ρωτάει «Καθαρός» ή «Κλασικός». Αλλάζει όποτε θες: Προφίλ › Ρυθμίσεις › Χάρτης. Παρατεταμένο πάτημα στον χάρτη: βάθος (και σε οργιές), απόσταση/πορεία από σένα, Πήγαινε εκεί, Χάρακας από εδώ, Ψάρι εδώ, Πρόγνωση εδώ.','The first time it asks “Clean” or “Classic”. Change it any time: Profile › Settings › Map. Long-press the map: depth (also in fathoms), distance/heading from you, Go there, Measure from here, Catch here, Forecast here.')]],
 ['1.7.1',[T('Νέος χάρακας: πατάς πάνω στον χάρτη για σημεία (χωρίς σταυρό και «Προσθήκη»). Σέρνεις ένα σημείο για να το μετακινήσεις, το πατάς για να το σβήσεις. Σε έξοδο ξεκινά αυτόματα από τη θέση σου. Μικρή μπάρα κάτω: απόσταση (km και nm), πορεία, χρόνος με την ταχύτητά σου (ή 3–20 kn), βάθος στο τελευταίο σημείο. Η μπάρα εξόδου κρύβεται όσο μετράς.','New ruler: tap the map to add points (no cross, no “Add”). Drag a point to move it, tap it to remove it. On a trip it starts from your position. A small bar: distance (km and nm), heading, time at your speed (or 3–20 kn), depth at the last point. The trip bar hides while measuring.'),T('Συρτή: στα «Τεχνητά στο νερό» μόνο τεχνητά (όχι καλάμια/σετ). Οδηγία για το «Ρίχνω» στην καρτέλα της συρτής βυθού.','Trolling: “Lures in the water” shows only lures (no rods/sets). A “Let out” hint in the bottom-trolling sheet.')]],
 ['1.7.0',[T('Συρτή βυθού: «Ρίχνω» μόλις πέσει το πρώτο μολύβι (προαιρετικά γράφεις τι δείχνει το βυθόμετρο). Όσο ρίχνεις, μεγάλος αριθμός «Σταμάτα στα Ν μολύβια» με τον βυθό εκεί που θα καταλήξει το δόλωμα και πόσα μέτρα πίσω. «Στον βυθό ✓» κλειδώνει τα μολύβια· αν το ξεχάσεις, κλειδώνει μόνο του μετά από 2′ σταθερής ταχύτητας.','Bottom trolling: “Let out” as the first lead goes in (optionally type what the sounder shows). While you let out, a big “Stop at N leads” with the bottom where the lure will end up and how far back. “On the bottom ✓” locks the leads; if you forget, it locks by itself after 2′ of steady speed.'),T('Μετά: «~2 οργ. πάνω από βυθό» ή «βαράει βυθό, μάζεψε». Κουμπί «Ακούμπησε» όταν νιώσεις τον βυθό: η εφαρμογή μαθαίνει πόσο βυθίζεται η δική σου αρματωσιά και διορθώνεται κάθε φορά.','Then: “~2 fm above bottom” or “hitting bottom, bring in”. A “Touched” button when you feel the bottom: the app learns how deep your own rig goes and improves each time.'),T('Ο δικός σου χάρτης βυθού: κάθε βάθος βυθόμετρου που γράφεις διορθώνει τον χάρτη (EMODnet) γύρω από εκείνο το σημείο και κρατιέται για τις επόμενες φορές.','Your own depth chart: each sounder depth you type corrects the chart (EMODnet) around that spot and is kept for next time.')]],
 ['1.6.9',[T('Χάρτης: οι ετικέτες κύματος δεν μπαίνουν πάνω στα βέλη των ρευμάτων και στα ψάρια· οι ετικέτες ανέμου/κύματος δεν κρύβονται κάτω από τα ψάρια. Τα βέλη των ρευμάτων παραμερίζουν από τα ψάρια. Κύμα με περίοδο κάτω από 2 s γράφεται «κυματάκι».','Map: wave labels avoid current arrows and catches; wind/wave labels no longer hide under catches. Current arrows move aside from catches. Waves under 2 s period show as “chop”.'),T('Προφίλ: έφυγαν τα «Τα σημεία μου» και «Παραγάδια, δίχτυα, ζεμπίλια», γιατί είναι ήδη καρτέλες στο Ημερολόγιο (Σημεία, Εργαλεία).','Profile: “My spots” and “Longlines, nets, pots” removed, they are already Logbook tabs (Spots, Gear).'),T('Μονάδες: νέα επιλογή «Βάθος» σε μέτρα, οργιές (1 οργιά = 1,83 m) ή πόδια. Ισχύει στο ψάρι, στη φόρμα, στα σημεία, στο «Τι δούλεψε», στο θερμοκλινές και στις προτάσεις.','Units: new “Depth” option in metres, fathoms (1 fathom = 1.83 m) or feet. Used on catches, the form, spots, “What worked”, the thermocline and suggestions.')]],
 ['1.6.8',[T('Πρόγνωση με νέα σειρά, όπως τις ερωτήσεις πριν βγεις: η μέρα και η καλύτερη ώρα → «Τώρα» (με τις ριπές) → «Ανά ώρα» με το «Γιατί» μέσα → πιθανότητες στα σημεία σου → τι δούλεψε → πίεση/άνεμος/σελήνη → «Κάτω από την επιφάνεια» (θερμοκρασία σε βάθος και ρεύμα σε μία κάρτα) → ήλιος και σελήνη.','Forecast in a new order, like the questions before you go out: the day and best time → “Now” (with gusts) → “By hour” with “Why” inside → chances at your spots → what worked → pressure/wind/moon → “Below the surface” (temperature at depth and current in one card) → sun and moon.'),T('Ριπές: φαίνονται στο «Τώρα» (πορτοκαλί από 5 Bft) και στο «Γιατί». Με δυνατές ριπές δεν γράφει πια «ήπιος άνεμος».','Gusts: shown in “Now” (orange from 5 Bft) and in “Why”. With strong gusts it no longer says “light wind”.')]],
 ['1.6.7',[T('Χάρτης: διορθώθηκε το λάθος που έδειχνε ψάρια και σημεία πάνω στη στεριά όταν απομακρυνόσουν (από την 1.6.1 κάθε σημάδι σπρωχνόταν προς τα κάτω από τα προηγούμενα). Τώρα κάθε σημάδι είναι ακριβώς στη θέση του, σε κάθε zoom.','Map: fixed catches and spots appearing on land when zoomed out (since 1.6.1 each marker was pushed down by the ones before it). Every marker now sits exactly on its position at any zoom.'),T('Αυτόματος έλεγχος: αν ποτέ ένα σημάδι ζωγραφιστεί σε λάθος θέση, η εφαρμογή το διορθώνει και στέλνει τα στοιχεία για να το δούμε.','Automatic check: if a marker is ever drawn in the wrong place, the app fixes it and reports the details.')]],
 ['1.6.6',[T('Η εφαρμογή ανοίγει πάντα στα Ελληνικά (ακόμη κι αν το κινητό είναι στα Αγγλικά). Για Αγγλικά: Προφίλ › Γλώσσα.','The app now always opens in Greek, even on an English phone. For English: Profile › Language.'),T('«Πού ψαρεύεις σήμερα;»: το «Αργότερα» έγινε «Παράλειψη» (κλείνει χωρίς αλλαγή), πιο σύντομα κείμενα στις κάρτες ώστε να χωρούν σε μία γραμμή, νέα φωτογραφία με καλάμια για το «Καλάμι».','“Where are you fishing today?”: “Later” is now “Skip” (closes without changes), shorter card texts that fit on one line, a new rods photo for “Rod”.'),T('Χάρτης: οι ομάδες ψαριών (με αριθμό) μπαίνουν πάνω σε πραγματικό σημείο ψαριού, όχι στον μέσο όρο που σε κάβο έπεφτε στη στεριά. Με τον άνεμο ανοιχτό, η στεριά φαίνεται καθαρά (το χρώμα και οι γραμμές του ανέμου είναι πολύ αχνά πάνω της).','Map: fish groups (with a number) sit on a real catch point, not on the average that fell on land at a cape. With wind on, land is clearly visible (wind colour and streaks are faint over land).')]],
 ['1.6.5',[T('Αρματωσιές συρτής βυθού: παράμαλλο, κενό πριν το 1ο μολύβι, απόσταση μολυβιών (οργιές), βάρος, στριφτάρι ανά Χ μολύβια, πόσα μολύβια. Έτοιμη η Deep Fishing (12–15 m fluorocarbon, 5 οργιές κενό, 160 g ανά 5 οργιές, στριφτάρι ανά 4, 30 μολύβια). Φτιάχνεις και δικές σου.','Bottom-trolling rigs: leader, gap before the first lead, lead spacing (fathoms), weight, a swivel every X leads, how many leads. Deep Fishing is ready (12–15 m fluorocarbon, 5-fathom gap, 160 g every 5 fathoms, a swivel every 4, 30 leads). You can add your own.'),T('Στη συρτή, δίπλα στην ταχύτητα: το βάθος του βυθού σε οργιές και μέτρα. «Προφίλ βυθού»: γράφημα με το ανάγλυφο του βυθού κατά μήκος της πορείας σου, πού ήταν το δόλωμα σε σχέση με τον βυθό και πού τσίμπησαν τα ψάρια· μένει και στην έξοδο στο Ημερολόγιο.','While trolling, next to the speed: bottom depth in fathoms and metres. “Seabed profile”: a chart of the seabed along your course, where the lure was relative to the bottom and where fish struck; it is also kept with the trip in the Logbook.'),T('Με αυτά υπολογίζεται πόσο πίσω είναι το δόλωμα: με 5 οργιές απόσταση είναι πολύ πιο πίσω απ’ ό,τι νόμιζε η εφαρμογή (π.χ. 31 μολύβια → ~290 m).','These set how far behind the lure is: with 5-fathom spacing it is much further back than the app assumed (e.g. 31 leads → ~290 m).')]],
 ['1.6.4',[T('«Καλύτερα σημεία»: διαλέγεις τεχνική (βυθού, καθετή, spinning, συρτή βυθού/αφρού, καλαμάρι) και πότε μπορείς (π.χ. βράδυ 17–22). Βγαίνουν τα 3 καλύτερα σημεία με αιτιολογία: καιρός ώρα-ώρα στο διάστημά σου, βάθος για την τεχνική, δύση/ανατολή, φεγγάρι για καλαμάρι, τα δικά σου ψάρια με την ίδια τεχνική.','“Best spots”: pick a technique (bottom, vertical, spinning, bottom/surface trolling, squid) and when you can go (e.g. evening 17–22). You get the 3 best spots with reasons: hour-by-hour weather in your window, depth for the technique, sunset/sunrise, moon for squid, your own catches with that technique.'),T('Ρολόι: σελίδα συρτής με μεγάλη ταχύτητα, δόνηση εκτός εύρους και μολύβια (αυτόματα ή ±). Τα ψάρια από το ρολόι μπαίνουν εκεί που ήταν το δόλωμα.','Watch: trolling page with a big speed readout, out-of-range vibration and leads (auto or ±). Catches from the watch are placed where the lure was.')]],
 ['1.6.3',[T('Συρτή βυθού: τα μολύβια βγαίνουν αυτόματα από τον βυθό (οργιές βυθού − 1, όπως 32 οργιές → 31 μολύβια). Δεν χρειάζεται να πατάς τίποτα, απλώς «ψάρι».','Bottom trolling: leads are worked out automatically from the bottom (bottom fathoms − 1, e.g. 32 fathoms → 31 leads). No need to tap anything, just “catch”.'),T('Βάθη σε οργιές όπως στο βυθόμετρο· η απόσταση πίσω από τη βάρκα σε μέτρα.','Depths in fathoms like on the sounder; distance behind the boat in metres.'),T('Δόνηση όταν ο βυθός μπροστά ανεβαίνει απότομα, με το πόσα μολύβια να μαζέψεις. Με − / + βάζεις δικό σου αριθμό ως το τέλος της εξόδου.','A vibration when the bottom ahead rises sharply, with how many leads to bring in. With − / + you set your own number until the end of the trip.')]],
 ['1.6.2',[T('Συρτή βυθού με μολύβια: βάζεις πόσα μολύβια έχεις έξω (1 μολύβι = 1 οργιά βάθος στα 3 kn). Η εφαρμογή δείχνει το βάθος του δολώματος και πόσα μέτρα πίσω είναι, ανάλογα με την ταχύτητα που πας.','Bottom trolling with leads: set how many leads are out (1 lead = 1 fathom deep at 3 kn). The app shows the lure depth and how far behind it is, from your actual speed.'),T('Κουμπιά − / + για τα μολύβια δίπλα στην ταχύτητα στον Χάρτη.','− / + lead buttons next to the speed on the Map.'),T('Προειδοποίηση με δόνηση όταν ο χάρτης βαθών δείχνει βυθό πιο ρηχό από το δόλωμα, με το πόσα μολύβια να μαζέψεις.','A vibration warning when the depth chart shows the bottom shallower than the lure, with how many leads to bring in.')]],
 ['1.6.1',[T('Νύχτα: το MOB και τα κουμπιά ψαριού ξεχωρίζουν πάντα (λευκό περίγραμμα), ο χάρτης είναι σκοτεινός και οι δείκτες φωτεινοί.','Night: MOB and the catch buttons always stand out (white ring), the map is dark and markers are bright.'),T('Χάρτης πιο καθαρός: χάρακας, ειδοποιήσεις και πηγές μπήκαν στο «⋯»· η συρτή και ο προσανατολισμός φαίνονται μόνο σε έξοδο, στη στήλη αριστερά (διορθώθηκε ο κύκλος κάτω από την άγκυρα).','Cleaner map: ruler, notifications and sources moved into “⋯”; trolling and orientation show only during a trip, in the left column (fixed the extra circle under the anchor).'),T('Το κύμα κόβεται ακριβώς στην ακτή (Κύπρος, Ελλάδα), λιγότερα βέλη ρευμάτων, πιο χαμηλή μπάρα ώρας.','Waves stop exactly at the coast (Cyprus, Greece), fewer current arrows, a lower time bar.'),T('Στο τέλος της εξόδου: «Τι έπιασες;» για τα ψάρια χωρίς είδος, με ένα πάτημα στα είδη που πιάνεις συχνότερα.','At the end of a trip: “What did you catch?” for catches without a species, one tap on your usual species.'),T('«Διόρθωση σημείου» σε κάθε ψάρι· στη συρτή η εφαρμογή μαθαίνει πόσο πίσω πάει το δόλωμά σου.','“Fix position” on every catch; with trolling the app learns how far back your lure runs.'),T('Ανοίγει πιο γρήγορα με αδύναμο σήμα (από τη μνήμη του κινητού) και στην έναρξη εξόδου κατεβαίνουν μόνα τους χάρτης και πρόγνωση.','Opens faster on a weak signal (from the phone’s memory) and starting a trip downloads the map and forecast automatically.'),T('Μικρότερα μηνύματα (πάτα για όλο το κείμενο), ολόκληρες λέξεις στις καρτέλες και στα Στρώματα, η πηγή της πρόγνωσης στην κάρτα «Τώρα».','Shorter messages (tap for the full text), full words in tabs and Layers, the forecast source on the “Now” card.')]],
 ['1.6.0',[T('Νέο: Συρτή. Στην έξοδο, στον Χάρτη, πάτα το κουμπί συρτής (αριστερά): διαλέγεις αφρού ή βυθού, ταχύτητα-στόχο και τα τεχνητά που έχεις στο νερό.','New: Trolling. During a trip, on the Map, tap the trolling button (left): pick surface or bottom, a target speed and the lures in the water.'),T('Μεγάλη ένδειξη ταχύτητας: πράσινη μέσα στο εύρος, πορτοκαλί/κόκκινη έξω, με δόνηση αν μείνεις έξω 20″.','Big speed readout: green within the range, orange/red outside, with a vibration if you stay outside for 20 s.'),T('Το ψάρι μπαίνει εκεί που ήταν το δόλωμα, πίσω από τη βάρκα πάνω στη διαδρομή σου: στον αφρό από τα μέτρα πετονιάς, στον βυθό από το βάθος, το μολύβι, την ταχύτητα και το παράμαλλο. Στον χάρτη μια κίτρινη γραμμή δείχνει πού ήταν η βάρκα.','The catch is placed where the lure was, behind the boat on your track: on the surface from the line out, on the bottom from the depth, lead, speed and leader. On the map a yellow line shows where the boat was.'),T('Στο ψάρι γράφονται αυτόματα ταχύτητα, πορεία, τεχνική και τεχνητά.','Speed, heading, technique and lures are saved with the catch automatically.')]],
 ['1.5.4',[T('«Διάλεξε στον χάρτη»: ανοίγει τον κανονικό Χάρτη (με τα σημεία, τα βάθη και τα στρώματά σου)· μετακινείς τον χάρτη και το σημείο είναι στον σταυρό.','“Pick on the map” now opens the full Map (with your spots, depths and layers); move the map and the point is under the crosshair.'),T('Η ετικέτα του σημείου ή της διαδρομής δεν κρύβει πια την ένδειξη ανέμου/κύματος.','The spot or route label no longer covers the wind/wave readout.'),T('Το ✕ στην επανάληψη εξόδου κλείνει και τη διαδρομή.','The ✕ on a trip replay also closes the route.')]],
 ['1.5.3',[T('Χάρτης: το κύμα και τα ρεύματα δεν ζωγραφίζονται πια πάνω στη στεριά σε όλη τη Μεσόγειο (π.χ. Ιταλία, Αδριατική), όχι μόνο σε Κύπρο και Ελλάδα.','Map: waves and currents are no longer drawn over land anywhere in the Mediterranean (e.g. Italy, the Adriatic), not just in Cyprus and Greece.'),T('Το κύμα φαίνεται και όταν βλέπεις μεγάλη περιοχή, χωρίς «κομμένα» τετράγωνα.','Waves now show when you zoom out over a large area too, without cut-off squares.'),T('Οι γραμμές βάθους είναι πιο αχνές από μακριά και δυναμώνουν με το ζουμ.','Depth lines are fainter when zoomed out and get stronger as you zoom in.')]],
 ['1.5.2',[T('Ο χάρτης ανοίγει πιο γρήγορα, ειδικά με αδύναμο σήμα: τα αρχεία του κατεβαίνουν όλα μαζί και όχι το ένα μετά το άλλο.','The map opens faster, especially on a weak signal: its files now download together instead of one after another.')]],
 ['1.5.1',[T('Τα email του λογαριασμού (επιβεβαίωση, νέος κωδικός) έρχονται στη γλώσσα της εφαρμογής σου.','Account emails (confirmation, new password) now come in your app language.')]],
 ['1.5.0',[T('Σύνδεση με Google: «Συνέχεια με Google» με ένα πάτημα, χωρίς κωδικό και χωρίς email επιβεβαίωσης.','Sign in with Google: “Continue with Google” in one tap, with no password and no confirmation email.')]],
 ['1.4.5',[T('Αλλαγή λογαριασμού: αν συνδεθείς με άλλον λογαριασμό και στο κινητό υπάρχουν δεδομένα του προηγούμενου, η εφαρμογή ρωτά αν θα μείνουν χωριστά ή θα μπουν και στον νέο. Πριν, έμπαιναν στον νέο χωρίς ερώτηση.','Switching account: if you sign in with another account and this phone has data from the previous one, the app asks whether to keep them separate or add them to the new one. Before, they were added without asking.'),T('Διόρθωση: σύνδεση αμέσως μετά από αποσύνδεση δεν «κρατούσε». Και αν ο λογαριασμός διαγράφηκε από τον server, βγαίνει κατανοητό μήνυμα αντί για «HTTP 409».','Fix: signing in right after signing out did not stick. And if the account was deleted on the server, a clear message shows instead of “HTTP 409”.')]],
 ['1.4.4',[T('Εγγραφή: αν πας στο email να πάρεις τον κωδικό και γυρίσεις, η φόρμα σε περιμένει στο βήμα του κωδικού. Νέο κουμπί «Επικόλληση», και ματάκι 👁 για να βλέπεις τον κωδικό πρόσβασης.','Sign-up: if you switch to your email to get the code and come back, the form waits at the code step. New “Paste” button, and an eye 👁 to show your password.')]],
 ['1.4.3',[T('Διόρθωση: ο σύνδεσμος επιβεβαίωσης στο email εγγραφής ανοίγει πλέον την εφαρμογή (πριν μπορούσε να βγάλει σελίδα 404).','Fix: the confirmation link in the sign-up email now opens the app (before it could show a 404 page).')]],
 ['1.4.2',[T('Λιγότερα δεδομένα σε κάθε ενημέρωση: δεν κατεβαίνουν πια στο παρασκήνιο ~4 MB αρχεία της παλιάς κλασικής έκδοσης.','Less data on every update: about 4 MB of old classic-version files are no longer downloaded in the background.')]],
 ['1.4.1',[T('Έλεγχος συστήματος: τα σφάλματα παλιότερων εκδόσεων (ήδη σταλμένα και διορθωμένα) δεν φαίνονται πια σαν τωρινά, και η λίστα καθαρίζεται με «Καθαρισμός λίστας».','System check: errors from older versions (already sent and fixed) no longer show as current, and the list can be cleared with “Clear list”.')]],
 ['1.4.0',[T('Λογαριασμός από την αρχή: στο καλωσόρισμα προτείνεται δωρεάν λογαριασμός (ή συνεχίζεις χωρίς). Μετά το πρώτο ψάρι ρωτά μία φορά αν θες αντίγραφο στο cloud.','Account from the start: the welcome screens suggest a free account (or you continue without). After your first catch it asks once if you want a cloud backup.'),T('Εγγραφή με κωδικό από το email (δουλεύει και μέσα στην εγκατεστημένη εφαρμογή), «Ξέχασα τον κωδικό» και νέος κωδικός, όλα εδώ.','Sign-up with a code from the email (works inside the installed app too), “Forgot password” and new password, all here.'),T('Φίλοι, Κοινότητα, ρολόι και επαφή ασφαλείας: σύνδεση επιτόπου, χωρίς να πας στο Προφίλ.','Friends, Community, watch and safety contact: sign in right there, without going to Profile.'),T('Νέο: «+ Παλιά έξοδος» στο Ημερολόγιο › Έξοδοι.','New: “+ Past trip” in Logbook › Trips.'),T('Η κλασική έκδοση αποσύρθηκε: οι παλιοί σύνδεσμοι ανοίγουν εδώ, με τα ίδια δεδομένα.','The classic version is retired: old links open here, with the same data.')]],
 ['1.3.3',[T('Διόρθωση: κατά την ενημέρωση, ο Εξοπλισμός και το αντίγραφο ασφαλείας μπορούσαν να βγάλουν σφάλμα μέχρι να ξανανοίξει η εφαρμογή. Και η αποθήκευση για offline παίρνει πάντα τα νέα αρχεία.','Fix: during an update, Tackle and backup could show an error until the app was reopened. Offline storage now always takes the new files.')]],
 ['1.3.2',[T('Πιο γρήγορο άνοιγμα στα ελληνικά: το λεξικό των αγγλικών φορτώνεται μόνο όταν η γλώσσα είναι αγγλικά. Και ο Εξοπλισμός φορτώνεται την πρώτη φορά που τον ανοίγεις.','Faster start in Greek: the English dictionary loads only when the language is English. The Tackle page now loads the first time you open it.'),T('Πρόγνωση › Δικά μου: τα σημεία με τα ψάρια σου ανοίγουν στον χάρτη της εφαρμογής (όχι στην κλασική έκδοση).','Forecast › Mine: your fish spots open on the app map (not the classic version).')]],
 ['1.3.1',[T('Η εφαρμογή ανοίγει πιο γρήγορα: ο χάρτης και οι σελίδες Βοήθεια, Σκάφος, Φίλοι και Έλεγχος συστήματος φορτώνονται την πρώτη φορά που τις ανοίγεις, όχι στο άνοιγμα. Δουλεύουν και offline όπως πριν.','The app opens faster: the map and the Help, Boat, Friends and System check pages load the first time you open them, not at startup. They still work offline.')]],
 ['1.3.0',[T('Ο οδηγός εξοπλισμού, η βιβλιοθήκη μοντέλων, οι φωτογραφίες ψαριών και ο αγγλικός οδηγός αποθηκεύονται για offline από την πρώτη φορά που ανοίγει η εφαρμογή, όχι μόνο αφού τα ανοίξεις με ίντερνετ.','The tackle guide, model library, fish photos and English guide are stored for offline use from the first launch, not only after you open them online.'),T('Χάρτης: όταν ανοίγεις τη θερμοκρασία νερού φαίνεται το μήνυμα «Φόρτωση…» μέχρι να έρθουν τα δεδομένα.','Map: turning on water temperature now shows a «Loading…» message until the data arrives.')]],
 ['1.2.9',[T('Καλύτερα σημεία από ακτή: τα σημεία είναι πάνω στην ακτογραμμή, ανά ~800 m, και βαθμολογούνται από το κύμα στην ακτή, τα βράχια με απότομο βυθό κοντά, το βάθος στην απόσταση της ρίψης (~200 m), τα μέτωπα τροφής και θερμοκρασίας κοντά και τα ψάρια σου εκεί. Διαλέγεις πόσο μακριά οδηγείς (10–50 km).','Best spots from the shore: the spots are on the coastline, every ~800 m, scored by waves at the shore, rocks with a steep drop close in, depth within casting range (~200 m), food and temperature fronts nearby and your catches there. Choose how far you drive (10–50 km).')]],
 ['1.2.8',[T('Καλύτερα σημεία με βάρκα: διαλέγεις πόσο μακριά πας (10/20/30/50 km από τη θέση σου, προεπιλογή 30). Τα βαθιά νερά (πάνω από 300 m) προτείνονται μόνο για τρόλινγκ, με πελαγικά ψάρια (παλαμίδα, κυνηγό).','Best spots by boat: choose how far you go (10/20/30/50 km from your position, default 30). Deep water (over 300 m) is suggested only for trolling, with pelagic fish (bonito, mahi-mahi).')]],
 ['1.2.7',[T('Καλύτερα σημεία: δείχνουν και πιθανά ψάρια για κάθε σημείο (από βάθος, βυθό, θερμοκρασία νερού, εποχή και τα δικά σου ψάρια εκεί). Δεν προτείνουν πια σημεία πολύ βαθιά: έως 300 m με βάρκα, 50 m από ακτή, 30 m για ψαροντούφεκο.','Best spots: they also show likely fish for each spot (from depth, seabed, water temperature, season and your own catches there). No more spots that are too deep: up to 300 m by boat, 50 m from shore, 30 m spearfishing.')]],
 ['1.2.6',[T('Καλύτερα σημεία: όσο είναι ανοιχτά, ψάχνουν ξανά μόνα τους όταν μετακινείς τον χάρτη, για την περιοχή που βλέπεις. Κίτρινο κουμπί κάτω για τη λίστα.','Best spots: while on, they search again by themselves as you move the map, for the area you see. Yellow button at the bottom for the list.')]],
 ['1.2.5',[T('Περασμένες μέρες: κρατιούνται όλες οι συνθήκες (άνεμος, ριπές, κύμα, ρεύμα, θερμοκρασία νερού, θερμοκλινές, ορατότητα, πίεση, καιρός, ήλιος, σελήνη, βαθμός ανά ώρα) και φαίνονται στην κάρτα «Συνθήκες εκείνης της μέρας».','Past days: all conditions are kept (wind, gusts, waves, current, water temperature, thermocline, visibility, pressure, weather, sun, moon, score by hour) and shown in the «Conditions that day» card.')]],
 ['1.2.4',[T('«Πού να πάω» και «Στον χάρτη»: αν μια τοποθεσία είναι στη στεριά (π.χ. το κέντρο μιας πόλης), ο χάρτης δείχνει την κοντινότερη θάλασσα, εκεί που ισχύει η πρόγνωση, με το όνομα της τοποθεσίας.','«Where to go» and «On the map»: if a place is on land (e.g. a town centre), the map shows the nearest sea, where the forecast applies, with the place name.')]],
 ['1.2.3',[T('Νέο: «Καλύτερα σημεία»: βρίσκει τα 5 καλύτερα σημεία γύρω σου από καιρό, τροφή, θερμοκρασία, ρεύμα, βυθό και τα ψάρια σου.','New: «Best spots»: finds the 5 best spots around you from weather, food, temperature, current, seabed and your catches.'),T('Ρεύματα στον χάρτη: στη Μεσόγειο από το πιο ακριβές μοντέλο Copernicus.','Currents on the map: in the Mediterranean from the more accurate Copernicus model.')]],
 ['1.2.2',[T('Ρολόι: νέα σελίδα «Σημείο» με βέλος, συναγερμός άγκυρας, ειδοποίηση 30 λεπτά πριν την καλύτερη ώρα, «Ώρα να γυρίσεις», βαθμός στο watch face, ηλιοσεληνιακές ώρες στο δαχτυλίδι.','Watch: new «Spot» page with arrow, anchor alarm, alert 30 minutes before the best time, «Time to head back», score on the watch face, solunar times on the ring.'),T('Χάρτης: τα βέλη ρεύματος δεν πέφτουν πια στη στεριά. Η «Τροφή» και το «Νερό δορυφόρου» έχουν κλίμακα χρωμάτων για τη Μεσόγειο, ώστε να φαίνονται οι διαφορές.','Map: current arrows no longer land on the shore. «Food» and «Satellite water» use a colour scale for the Mediterranean, so differences show.'),T('Ειδοποιήσεις: «Στον χάρτη» και «Πού να πάω» σε πάνε πάντα στον Χάρτη. Τα «Σημείο χάρτη» δεν στέλνουν πια ειδοποιήσεις (ανοίγουν από τις Ειδοποιήσεις).','Notifications: «On the map» and «Where to go» always take you to the Map. «Map point» places no longer send alerts (turn them on in Notifications).')]],
 ['1.2.1',[T('Περασμένες μέρες: χθες και προχθές εμφανίζονται αμέσως, ώρα με ώρα, αριστερά από το «Σήμερα». Πριν, εμφανίζονταν μόνο οι μέρες από την ημέρα της εγκατάστασης και μετά.','Past days: yesterday and the day before now appear right away, hour by hour, to the left of «Today». Before, only days from the day of installation onward appeared.')]],
 ['1.2.0',[T('Ρολόι Garmin, νέο σχέδιο: δαχτυλίδι 24 ωρών με τις καλές ώρες, ανατολή και δύση στη σελίδα Σήμερα.','Garmin watch, new design: 24-hour ring with the good hours, sunrise and sunset on the Today page.'),T('Έξοδος στο ρολόι: δαχτυλίδι ως την ώρα επιστροφής, πόσο απομένει, ψάρια, km και κόμβοι.','Trip on the watch: ring up to your return time, time left, fish, km and knots.'),T('Πίεση στο ρολόι: γράφημα 12 ωρών με κλίμακα και σημάδι στην επόμενη κορυφή ή πάτο.','Pressure on the watch: 12-hour chart with scale and a mark at the next peak or low.'),T('Νέα εικονίδια στο μενού START, οθόνη «Καταγράφηκε» με το νούμερο του ψαριού στην έξοδο, και κόκκινη οθόνη τη νύχτα.','New icons in the START menu, a «Saved» screen with the fish number in the trip, and a red screen at night.')]],
 ['1.1.2',[T('Μήνυμα για καλή μέρα και από το προηγούμενο βράδυ: «🌙 Καλό ψάρεμα αύριο» με τοποθεσία και ώρα. Στις Ειδοποιήσεις διαλέγεις βράδυ, πρωί ή και τα δύο.','Good-day message also the evening before: «🌙 Good fishing tomorrow» with place and time. In Alerts choose evening, morning or both.'),T('Πρόγνωση: οι προηγούμενες μέρες (έως 7) φαίνονται αριστερά στη λωρίδα των ημερών, με τον βαθμό τους. Ο βαθμός κάθε μέρας αποθηκεύεται ανά τοποθεσία (έως 90 μέρες), και βλέπεις και πόσα ψάρια έπιασες εκείνη τη μέρα.','Forecast: previous days (up to 7) appear on the left of the day strip with their score. Each day’s score is saved per place (up to 90 days), and you also see how many fish you caught that day.')]],
 ['1.1.1',[T('Ημερολόγιο: η διαγραφή ψαριού δεν «αναβοσβήνει» πια· οι φωτογραφίες μένουν στη θέση τους και η λίστα δεν πηδάει.','Logbook: deleting a catch no longer flickers; photos stay in place and the list doesn’t jump.')]],
 ['1.1.0',[T('Πρόγνωση: ρεύμα θάλασσας τώρα, για τις επόμενες 24 ώρες και σε βάθος (Copernicus).','Forecast: sea current now, for the next 24 hours and at depth (Copernicus).'),T('Χάρτης: νέες στρώσεις «Τροφή» (χλωροφύλλη) και «Νερό δορυφόρου», για να βρίσκεις μέτωπα.','Map: new «Food» (chlorophyll) and «Satellite water» layers to find fronts.'),T('Κάρτα «Τώρα»: «Πού να πάω» και «Στον χάρτη» στη θέση της έναρξης εξόδου και του νέου ψαριού.','«Now» card: «Where to go» and «On the map» instead of start trip and new catch.'),T('Πρωινό μήνυμα για σήμερα, μόνο όταν αξίζει.','Morning message for today, only when it’s worth it.'),T('Ρολόι Garmin: έξοδος με καταγραφή δραστηριότητας «Ψάρεμα» και διαδρομή GPS.','Garmin watch: trips recorded as a «Fishing» activity with a GPS track.'),T('Ειδοποιήσεις: πάτα μία για «Πρόγνωση εκεί» ή «Στον χάρτη».','Notifications: tap one for «Forecast there» or «On the map».')]],
 ['1.0.1',[T('Έλεγχος συστήματος: οι γραμμές αλλάζουν μία-μία όσο τελειώνει κάθε έλεγχος, χωρίς να «αναβοσβήνει» η σελίδα.','System check: rows update one by one as each check finishes, without the page flickering.')]],
 ['1.0.0',[T('Νέο όνομα και νέο logo: η εφαρμογή λέγεται πλέον Alkyon (αλκυόνη). Η αλκυόνη ξέρει ακριβώς τη στιγμή να βουτήξει, όπως η πρόγνωση σου λέει τη σωστή ώρα για ψάρεμα.','New name and logo: the app is now called Alkyon (the kingfisher). The kingfisher knows the exact moment to dive, just as the forecast tells you the right time to fish.'),T('Νέα διεύθυνση: dinospapani.github.io/Alkyon. Τα δεδομένα σου (ψάρια, σημεία, έξοδοι, φωτογραφίες, ρυθμίσεις) μεταφέρθηκαν αυτόματα. Πρόσθεσε τη νέα εφαρμογή στην αρχική οθόνη και σβήσε την παλιά.','New address: dinospapani.github.io/Alkyon. Your data (catches, spots, trips, photos, settings) moved over automatically. Add the new app to your home screen and remove the old one.'),T('Οι ειδοποιήσεις ξαναρυθμίζονται μόνες τους με τη νέα διεύθυνση. Αν δεν έρχονται, άνοιξε Προφίλ › Ειδοποιήσεις μία φορά.','Alerts set themselves up again at the new address. If they stop, open Profile › Alerts once.'),T('Νέο Telegram bot ασφαλείας: @AlkyonMaydayBot. Οι επαφές ασφαλείας πρέπει να ξανασυνδεθούν (Προφίλ › Επαφή ασφαλείας).','New safety Telegram bot: @AlkyonMaydayBot. Safety contacts need to link again (Profile › Safety contact).'),T('Οι εκδόσεις ξεκινούν από την αρχή: αυτή είναι η 1.0.0. Και η εφαρμογή του ρολογιού Garmin λέγεται πλέον Alkyon.','Versions start over: this is 1.0.0. The Garmin watch app is now called Alkyon too.')]],
 ['v31z554',[T('Διόρθωση: το κουμπί ⓘ (πηγές χάρτη) στον χάρτη','Fix: the ⓘ (map sources) button on the map')]],
 ['v31z553',[T('Ρολόι Garmin: ειδοποίηση πριν την κορυφή ή τον πάτο της πίεσης, και όταν αρχίζει να πέφτει ή να ανεβαίνει','Garmin watch: alert before a pressure peak or low, and when it starts to fall or rise')]],
 ['v31z552',[T('Ρολόι Garmin: πρόγνωση, ειδοποίηση πίεσης και καταγραφή ψαριού από το ρολόι (Προφίλ › Ρολόι Garmin)','Garmin watch: forecast, pressure alert and catch logging from the watch (Profile › Garmin watch)')]],
 ['v31z551',[T('Θερμοκλινές: δουλεύει και κοντά στην ακτή (βρίσκει την πλησιέστερη θάλασσα)','Thermocline: works near the coast too (finds the nearest sea)'),T('Έλεγχος συστήματος: σωστός έλεγχος λογαριασμού','System check: correct account check')]],
 ['v31z550',[T('Προφίλ › Έλεγχος συστήματος: τι δουλεύει και τι όχι, με ένα πάτημα','Profile › System check: what works and what doesn’t, in one tap'),T('«Θα βγω»: χάρτης και πρόγνωση κατεβαίνουν μόνα τους για χρήση χωρίς σήμα (WiFi ή 4G/5G)','“I’ll go out”: map and forecast download by themselves for use without signal (WiFi or 4G/5G)'),T('Αντίγραφο στο cloud κάθε εβδομάδα, με επαναφορά','Weekly cloud backup, with restore'),T('Φωνή: πόσα ψάρια, δόλωμα, απελευθέρωση, λαγοκέφαλος· και στα μεγάλα κουμπιά','Voice: how many, bait, released, toadfish; also on the big buttons'),T('«Για σένα»: ο δικός σου βαθμός στην κάρτα της ημέρας','“For you”: your own score on the day card'),T('Ανοίγει γρήγορα και με αδύναμο σήμα','Opens fast even with weak signal')]],
 ['v31z549',[T('Διαγραφή ψαριού ή σημείου κατευθείαν από τον χάρτη','Delete a catch or spot straight from the map'),T('Εργαλεία: το «Στον χάρτη» δείχνει και όσα έχουν ανέβει','Gear: “On the map” also shows finished sets'),T('Σκάφος: προτεινόμενες λήξεις (δίπλωμα, σωσίβια, τρέιλερ, μαρίνα…) ή δικές σου','Boat: suggested expiries (licence, lifejackets, trailer, marina…) or your own')]],
 ['v31z548',[T('Ορατότητα νερού: πιο αξιόπιστη λήψη από δορυφόρο','Water visibility: more reliable satellite data')]],
 ['v31z547',[T('Σελίδα «Πώς δουλεύει» στο Προφίλ › Γνώση','“How it works” page in Profile › Knowledge')]],
 ['v31z545',[T('«Θα βγω αυτή τη μέρα»: υπενθυμίσεις και ειδοποίηση αν χαλάσει','“I’ll go out this day”: reminders and an alert if it turns'),T('Στην έξοδο: καιρός, δύση και «ώρα να γυρίσεις», και με κλειστό κινητό','On trips: weather, sunset and “time to head back”, even with the phone locked'),
   T('Λαγοκέφαλοι: κουμπί 🐡, δεν μετράνε ως ψάρια','Toadfish: 🐡 button, not counted as catches'),T('Μεγάλα κουμπιά και νυχτερινή λειτουργία στην έξοδο','Big buttons and night mode on trips'),
   T('Στόχοι, ρεκόρ, σύγκριση χρονιών, εποχή ειδών','Goals, records, year comparison, species seasons'),T('Θερμοκλινές, μέτωπα θερμοκρασίας, «τι δούλεψε σε παρόμοιες μέρες»','Thermocline, temperature fronts, “what worked on similar days”'),
   T('Χάρτης: περιστροφή με δύο δάχτυλα, μέρες στη μπάρα ώρας, κοινή έξοδος με φίλους','Map: two-finger rotation, days on the time bar, shared trips with friends')]]
];
function verN(v){ var s=/^v?(\d+)\.(\d+)(?:\.(\d+))?$/.exec(v||''); if(s) return 1e7+(+s[1])*1e4+(+s[2])*100+(+(s[3]||0)); var m=/v(\d+)z(\d+)/.exec(v||''); return m?+m[1]*1000+(+m[2]):0; }
/* ---------- σελίδα ---------- */
B.view('help',{title:T('Πώς δουλεύει','How it works'),mount:function(el){
  var page=h('div',{class:'page help'});
  page.append(h('div',{class:'top'},h('div',{style:{display:'flex',alignItems:'center',gap:'12px'}},h('a',{class:'iconbtn',href:'#profile','aria-label':T('Πίσω','Back'),html:B.iconSvg('back')}),h('h1',{class:'lt',text:T('Πώς δουλεύει','How it works')}))));
  HELP.forEach(function(sec,si){ var d=h('details',{class:'card hsec',open:si===0}); d.append(h('summary',null,h('b',{text:sec[0]})));
    var ul=h('ul',{class:'hlist'}); sec[1].forEach(function(it){ ul.append(h('li',null,h('span',{text:it[0]}),it[1]?h('a',{href:it[1],class:'hgo',text:it[2]+' ›'}):null)); }); d.append(ul); page.append(d); });
  page.append(h('section',{class:'card'},h('h2',{text:T('Τι νέο υπάρχει','What’s new')}),NEWS.slice(0,3).map(function(n){ return h('div',{class:'hnews'},h('small',{text:n[0]}),h('ul',{class:'hlist'},n[1].map(function(x){ return h('li',{text:x}); }))); })));
  page.append(h('p',{class:'foot',text:(window.ALKYON_VERSION||'')}));
  el.replaceChildren(page); }});
/* ---------- «Τι νέο» μία φορά μετά την ενημέρωση ---------- */
function whatsNew(){ var seen=ls.get('alkyon-v4-news',null), top=NEWS[0][0];
  var onb=false; try{ onb=!!localStorage.getItem('alkyon-onboard'); }catch(e){}
  if(!seen){ ls.set('alkyon-v4-news',onb&&hasHistory()?'v31z532':top); seen=ls.get('alkyon-v4-news',top); }
  var fresh=NEWS.filter(function(n){ return verN(n[0])>verN(seen); }); if(!fresh.length) return;
  if(document.querySelector('.sheet,.sppage,.bigtrip')){ setTimeout(whatsNew,4000); return; }
  /* v31z549: όχι στη μέση εξόδου· περιμένει να τελειώσει */
  var onTrip=false; try{ onTrip=document.body.classList.contains('ontrip')||!!(B.trip&&B.trip.active&&B.trip.active()); }catch(e){} if(onTrip){ setTimeout(whatsNew,120000); return; }
  ls.set('alkyon-v4-news',top);
  var items=[]; fresh.forEach(function(n){ items=items.concat(n[1]); }); items=items.slice(0,8);
  var sh=B.sheet({title:T('Τι νέο υπάρχει','What’s new'),body:h('div',{class:'bform'},h('ul',{class:'hlist hnew'},items.map(function(x){ return h('li',{text:x}); })),
    h('a',{class:'btn full',href:'#help',text:T('Όλα στο «Πώς δουλεύει»','All in “How it works”'),onclick:function(){ sh.close(); }}))}); }
/* χρήστης που είχε ήδη δεδομένα πριν από αυτή τη σελίδα = παλιός χρήστης */
function hasHistory(){ try{ return ['bites','trips','spots'].some(function(k){ return B.store.raw(k).length>0; })||!!localStorage.getItem('alkyon-notify'); }catch(e){ return false; } }
setTimeout(whatsNew,6000);
B.help={news:NEWS};
})();
